import os
import sys
import json
import glob
from datetime import datetime, timezone
from typing import Optional, Any

AHCLAUDE_DIR = os.path.expanduser("~/.ahdev")
LOG_PREFIX = "hook"
MAX_KEEP_DAYS = 7


def _get_log_filename(date_str: Optional[str] = None) -> str:
    # 统一日志文件名：hook.log（便于测试验证）
    return os.path.join(AHCLAUDE_DIR, f"{LOG_PREFIX}.log")


def _cleanup_old_logs():
    try:
        os.makedirs(AHCLAUDE_DIR, exist_ok=True)
    except OSError as e:
        print(f"[警告] 无法创建目录 {AHCLAUDE_DIR}: {e}", file=sys.stderr)
    pattern = os.path.join(AHCLAUDE_DIR, f"{LOG_PREFIX}-*.log")
    log_files = glob.glob(pattern)
    
    cutoff = datetime.now(timezone.utc).timestamp() - (MAX_KEEP_DAYS * 86400)
    
    for log_file in log_files:
        try:
            if os.path.getmtime(log_file) < cutoff:
                os.remove(log_file)
        except OSError:
            pass


def hook_log(hook_type: str, message: str, session_id: Optional[str] = None,
             extra: Optional[dict] = None):
    timestamp = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    
    session_prefix = f"[session:{session_id[:8]}...]" if session_id else ""
    extra_str = f" | {json.dumps(extra, ensure_ascii=False)}" if extra else ""
    log_line = f"[{timestamp}] [{hook_type}] {session_prefix} {message}{extra_str}\n"
    
    _cleanup_old_logs()
    
    log_file = _get_log_filename()
    try:
        with open(log_file, 'a', encoding='utf-8') as f:
            f.write(log_line)
    except OSError as e:
        print(f"[警告] 无法写入日志 {log_file}: {e}", file=sys.stderr)


def hook_log_raw(hook_type: str, input_data: dict):
    timestamp = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    
    session_id = input_data.get("session_id", "")
    session_prefix = f"[session:{session_id[:8]}...]" if session_id else ""
    
    raw_json = json.dumps(input_data, ensure_ascii=False, indent=2)
    
    _cleanup_old_logs()
    
    log_file = _get_log_filename()
    try:
        with open(log_file, 'a', encoding='utf-8') as f:
            f.write(f"\n{'='*80}\n")
            f.write(f"[{timestamp}] [{hook_type}] {session_prefix} RAW_INPUT\n")
            f.write(f"{'='*80}\n")
            f.write(raw_json + "\n")
            f.write(f"{'='*80}\n\n")
    except OSError as e:
        print(f"[警告] 无法写入日志 {log_file}: {e}", file=sys.stderr)
